class Router:
    def __init__(self):
        self.routes = {}

    def add(self, method, path, handler):
        self.routes[(method, path)] = handler

    def dispatch(self, method, path, req):
        h = self.routes.get((method, path))
        if not h: raise KeyError('no route')
        return h(req)

